<div class="chips"><a class="chip <?= ($_GET['jenis']??'')===''?'active':'' ?>" href="?page=dokumen">Semua</a><?php foreach(['Penawaran','Surat Jalan','Invoice'] as $type): ?><a class="chip <?= ($_GET['jenis']??'')===$type?'active':'' ?>" href="?page=dokumen&jenis=<?= urlencode($type) ?>"><?= h($type) ?></a><?php endforeach; ?></div><section class="panel"><div class="panel-head"><div><h2>Daftar Dokumen</h2><p>Penawaran, surat jalan, dan invoice penyewaan</p></div><div class="doc-actions"><button class="btn light" onclick="window.print()">Cetak / Simpan PDF</button><?php if(current_role()==='admin'): ?><details class="doc-create"><summary class="btn primary">＋ Buat Dokumen</summary><form method="post" class="doc-form"><?= csrf_field() ?><input type="hidden" name="action" value="create_document"><label>Jenis Dokumen</label><select class="field" name="jenis"><option>Penawaran</option><option>Surat Jalan</option><option>Invoice</option></select><label>Pelanggan</label><input class="field" name="pelanggan" value="CV Maju Jaya"><button class="btn primary full">Terbitkan Dokumen Demo</button></form></details><?php endif; ?></div></div><div class="table-wrap"><table><thead><tr><th>No. Dokumen</th><th>Tanggal</th><th>Pelanggan</th><th>Jenis</th><th>Status</th><th>Pratinjau</th><?php if(current_role()==='admin'): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php foreach($store['dokumen'] as $d): if(!empty($_GET['jenis']) && $d['jenis']!==$_GET['jenis'])continue; ?><tr><td><b><?= h($d['kode']) ?></b></td><td><?= h($d['tanggal']) ?></td><td><?= h($d['pelanggan']) ?></td><td><?= h($d['jenis']) ?></td><td><?= status_badge($d['status']) ?></td><td><button class="icon-btn" onclick="alert('Dokumen demo: <?= h($d['kode']) ?>')">↗</button></td><?php if(current_role()==='admin'): ?><td><?php if($d['jenis']==='Invoice' && $d['status']!=='Lunas'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="mark_invoice_paid"><input type="hidden" name="kode" value="<?= h($d['kode']) ?>"><button class="btn light compact">Catat Lunas</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section>
